'use client';
import {useState,useEffect,useMemo} from 'react';
import {motion,AnimatePresence,MotionConfig,useReducedMotion} from 'motion/react';
import {ArrowLeft,ArrowRight,Map,MapPin,Compass,CalendarDays,Users,User,Clock,ChevronDown,Menu,X,Sparkles,Ticket,Check,Plus,Heart,Search,SlidersHorizontal,Star,Zap,Mountain,ArrowUpRight,UtensilsCrossed,Footprints,Bell,Shield,Settings,LogOut,CheckCircle2,Loader2,Coffee,Flag,Navigation,CheckCheck,Trash2,Mail,LockKeyhole,ExternalLink,Route,LayoutDashboard,Copy,PartyPopper,RefreshCw,CheckSquare,Circle,Play,Pause,Info,Link as LinkIcon,Minus} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription } from '@/components/ui/dialog';
import { Sheet,SheetContent,SheetHeader,SheetTitle,SheetTrigger } from '@/components/ui/sheet';
import { Switch } from '@/components/ui/switch';
import {Toaster,toast} from 'sonner';
import {TeamPage} from '@/components/sikka/team-page';
import {ParkMap} from '@/components/sikka/park-map';
import {rides,featured,photos,lands,categoryName,initialVisit,makeActivities,timeLabel,meals,type Ride,type Visit} from '@/lib/sikka-data';

type Page='home'|'rides'|'map'|'detail'|'visits'|'create'|'members'|'family'|'selection'|'meals'|'preview'|'payment'|'generating'|'plan'|'live'|'recap'|'login'|'signup'|'forgot'|'profile'|'preferences'|'privacy'|'notifications'|'admin'|'sources'|'invite'|'team';
const navigation=[{key:'home',label:'الرئيسية',icon:Compass},{key:'rides',label:'الألعاب والتجارب',icon:Ticket},{key:'map',label:'خريطة الملاهي',icon:Map},{key:'visits',label:'زياراتي',icon:CalendarDays}];
function newId(){return typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),n=>n.toString(16).padStart(2,'0')).join('');}
const steps=['تفاصيل الطلعة','مين معنا؟','ألعابكم','وقت البريك','المعاينة'];
function Logo(){return <span className="logo"><span>سكة<svg viewBox="0 0 100 18" aria-hidden="true"><path d="M0 14Q20 -6 35 8T70 7T100 8" stroke="currentColor" fill="none" strokeWidth="4"/><circle cx="32" cy="6" r="4" fill="#ed1d2d"/><circle cx="41" cy="10" r="4" fill="#ffc928"/></svg></span><small>SIKKA</small></span>}
function Photo({asset,alt,className='',...props}:{asset:string;alt:string;className?:string;[key:string]:unknown}){const [fallback,setFallback]=useState(false);return <img loading="lazy" {...props} src={fallback?photos[asset]?.url:`/api/media/${asset}`} className={className} alt={alt} onError={()=>setFallback(true)}/>}
function PageTitle({label,title,description,children}:{label?:string;title:string;description?:string;children?:React.ReactNode}){return <div className="page-title"><div>{label&&<div className="eyebrow">{label}</div>}<h1>{title}</h1>{description&&<p>{description}</p>}</div>{children}</div>}
function Empty({title,description,action,onClick}:{title:string;description:string;action:string;onClick:()=>void}){return <div className="empty-state"><span className="empty-icon"><Ticket size={44}/></span><h2>{title}</h2><p>{description}</p><Button onClick={onClick}>{action}<Plus size={17}/></Button></div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function RideCard({ride,onOpen,onSelect,selected,favorite,onFavorite}:{ride:Ride;onOpen:()=>void;onSelect?:()=>void;selected?:boolean;favorite?:boolean;onFavorite?:()=>void}){return <motion.article layout className={`ride-card ${selected?'is-selected':''}`}><button className="ride-cover" onClick={onOpen}>{ride.photo?<Photo asset={ride.photo} alt={ride.name}/>:<div className={`ride-illustration land-${ride.land}`}><Mountain size={76}/><span>{ride.landName}</span></div>}<span className={`ride-category cat-${ride.category}`}><Zap size={13}/>{categoryName[ride.category]||'تجربة'}</span><span className="cover-arrow"><ArrowUpRight size={21}/></span></button>{onFavorite&&<button className={`favorite ${favorite?'saved':''}`} aria-label={`حفظ ${ride.name} بالمفضلة`} onClick={onFavorite}><Heart size={18} fill={favorite?'currentColor':'none'}/></button>}<div className="ride-card-body"><span className="ride-land"><MapPin size={13}/>{ride.landName}</span><button className="ride-name" onClick={onOpen} dir="ltr">{ride.name}</button><p>{ride.description}</p><div className="ride-bottom"><span><span className="status-dot"/>الحالة غير متصلة</span>{onSelect?<Button size="sm" variant={selected?'default':'outline'} onClick={onSelect}>{selected?<Check size={16}/>:<Plus size={16}/>} {selected?'ضمن اختياراتك':'أضفها لطلعتك'}</Button>:<button className="text-link" onClick={onOpen}>شوف التفاصيل<ArrowLeft size={14}/></button>}</div></div></motion.article>}

export default function Sikka(){
const [route,setRoute]=useState('home'),[ready,setReady]=useState(false),[visits,setVisits]=useState<Visit[]>([]),[activeId,setActiveId]=useState(''),[favorites,setFavorites]=useState<string[]>([]),[user,setUser]=useState<{name:string;height:string;thrill:string}|null>(null),[privacy,setPrivacy]=useState({location:false,email:true,whatsapp:false}),[family,setFamily]=useState<{name:string;age:string;height:string}[]>([]),[modal,setModal]=useState<'complete'|'delay'|'replan'|'family'|'delete'|null>(null),[query,setQuery]=useState(''),[category,setCategory]=useState('ALL'),[land,setLand]=useState('ALL'),[planTab,setPlanTab]=useState('group'),[paymentState,setPaymentState]=useState('idle'),[rating,setRating]=useState(0),[completedFor,setCompletedFor]=useState<string[]>([]),[note,setNote]=useState(''),[delayReason,setDelayReason]=useState('راحة'),[pendingReplan,setPendingReplan]=useState(false),[arrived,setArrived]=useState(false),[menuOpen,setMenuOpen]=useState(false);
const [draft,setDraft]=useState<Visit>({...initialVisit,id:'',name:'',date:'',arrival:'',members:[],selected:[]});
const reduced=useReducedMotion();const page=(route.split('/')[0]||'home') as Page;const detail=rides.find(r=>r.slug===route.split('/')[1])||featured[0];const visit=visits.find(v=>v.id===activeId)||null;
useEffect(()=>{function onHash(){setRoute(location.hash.slice(1)||'home');setQuery('');window.scrollTo(0,0);}onHash();window.addEventListener('hashchange',onHash);try{const data=JSON.parse(localStorage.getItem('sikka-demo-v1')||'null');if(data){setVisits(data.visits||[]);setFavorites(data.favorites||[]);setUser(data.user||null);setFamily(data.family||[]);setActiveId(data.activeId||'');setPrivacy(data.privacy||{location:false,email:true,whatsapp:false});}}catch{}setReady(true);return()=>window.removeEventListener('hashchange',onHash)},[]);
useEffect(()=>{if(ready)localStorage.setItem('sikka-demo-v1',JSON.stringify({visits,favorites,user,family,activeId,privacy}));},[visits,favorites,user,family,activeId,privacy,ready]);
useEffect(()=>{if(page!=='generating')return;const timer=setTimeout(()=>{if(visit)updateVisit({status:'GENERATED'});go('plan');},2400);return()=>clearTimeout(timer)},[page]);
function go(target:string){if(location.hash==='#'+target){setRoute(target);window.scrollTo(0,0);}else location.hash=target;}
function updateVisit(patch:Partial<Visit>){setVisits(all=>all.map(v=>v.id===activeId?{...v,...patch}:v));}
function ensureVisit(target:string){if(!visit){toast.info('خلّنا نجهّز طلعتك أول');go('create');return;}go(target);}
function toggleFavorite(id:string){setFavorites(f=>f.includes(id)?f.filter(x=>x!==id):[...f,id]);}
function toggleRide(id:string){if(!visit)return;updateVisit({selected:visit.selected.includes(id)?visit.selected.filter(x=>x!==id):[...visit.selected,id]});}
function sample(){const v={...initialVisit,id:newId(),name:'طلعة الشباب • تجربة',members:[user?.name||'عبدالعزيز','محمد','نواف'],paid:true,approved:true,status:'APPROVED'};setVisits(a=>[...a,v]);setActiveId(v.id);toast.success('فتحنا زيارة توضيحية محفوظة على هذا الجهاز');go('plan');}
function openVisit(v:Visit){setActiveId(v.id);go(v.status==='COMPLETED'?'recap':v.status==='ACTIVE'?'live':v.paid?'plan':'preview');}
const activities=useMemo(()=>visit?makeActivities(visit):[],[visit]);const current=activities.find(a=>!visit?.completed.includes(a.key));const filtered=rides.filter(r=>(category==='ALL'||r.category===category)&&(land==='ALL'||r.land===land)&&(`${r.name} ${r.landName}`.toLowerCase().includes(query.toLowerCase())));
const stepIndex=page==='create'?0:page==='members'?1:page==='selection'?2:page==='meals'?3:4;
function stepBar(){return <div className="step-bar">{steps.map((s,i)=><button key={s} className={i===stepIndex?'current':i<stepIndex?'done':''} disabled={!visit&&i>0} onClick={()=>{if(i===0&&visit)setDraft({...visit});go(['create','members','selection','meals','preview'][i]);}}><span>{i<stepIndex?<Check size={14}/>:i+1}</span><label>{s}</label></button>)}</div>}
function renderTimeline(individual=false){return <div className="timeline">{activities.filter(a=>!individual||a.participants.includes(visit?.members[0]||'')).map((a,i)=>{const done=visit?.completed.includes(a.key);const r=rides.find(r=>r.slug===a.key);return <motion.div layout className={`timeline-item ${done?'done':''} ${current?.key===a.key?'current':''}`} key={a.key}><div className="timeline-time">{visit&&timeLabel(a.offset,visit)}<span>{a.minutes} دقيقة</span></div><div className="timeline-dot">{done?<Check size={15}/>:a.kind==='RIDE'?<Ticket size={15}/>:<UtensilsCrossed size={15}/>}</div><article className="activity-card">{r?.photo?<Photo asset={r.photo} alt={a.title}/>:<span className="activity-symbol">{a.kind==='SNACK'?<Coffee/>:<UtensilsCrossed/>}</span>}<div className="activity-info"><small>{a.kind==='RIDE'?r?.landName:'بريك يجمعنا'}{done&&' • مكتملة'}</small><h3 dir={a.kind==='RIDE'?'ltr':'rtl'}>{a.title}</h3><p>{a.participants.join('، ')}</p><span className="activity-meta"><Clock size={13}/>{a.minutes} د {visit?.ratings[a.key]?` • تقييمك ${visit.ratings[a.key]}/٥`:''}</span></div>{a.kind==='RIDE'&&<button className="activity-link" aria-label={`تفاصيل ${a.title}`} onClick={()=>go('detail/'+a.key)}><ArrowUpRight size={18}/></button>}</article></motion.div>})}</div>}

function content(){
if(page==='team')return <TeamPage/>;
if(page==='home')return <>
<section className="hero"><Photo asset="park" className="hero-photo" alt="Falcons Flight في Six Flags القدية ليلًا" loading="eager"/><div className="hero-shade"/><svg className="hero-track" viewBox="0 0 1440 650" aria-hidden="true"><path d="M-50 480C200 80 240 660 510 390S860 -80 970 50"/></svg><div className="hero-inner container"><div className="hero-copy"><div className="hero-kicker"><span/>الوناسة لها سكة</div><h1>القدية<br/>صارت ذكية<span className="headline-spark">✦</span></h1><p>ألعاب أكثر، حيرة أقل.<br/>خطّط طلعتك على جوّك، وخلّ الباقي علينا.</p><div className="hero-actions"><Button className="hero-cta" onClick={()=>go('create')}>نخطّط يومك؟<ArrowLeft size={20}/></Button><button className="hero-secondary" onClick={()=>go('map')}><Map size={18}/>استكشف الملاهي</button></div><div className="hero-note"><Users size={16}/>لحالك، مع أصحابك، أو مع العائلة… سكة تجمعكم.</div></div><div className="hero-photo-caption"><span>Six Flags Qiddiya City</span><small>مدينة التشويق، على طريقتك</small></div></div><div className="hero-bottom"><span>خلّ المغامرة تبدأ</span><div/><ArrowLeft size={18}/></div></section>
<section className="intro-strip container"><div><Compass/><span>استكشف قبل توصل</span><small>الألعاب والخريطة بدون تسجيل</small></div><div><Sparkles/><span>خطّة على جوّكم</span><small>رغبات مختلفة، ويوم واحد يجمعكم</small></div><div><Navigation/><span>رفيقك طول اليوم</span><small>نشاطك الحالي، والوجهة اللي بعدها</small></div></section>
<section className="section container"><div className="section-heading"><div><div className="eyebrow">جرعتك من الحماس</div><h2>أي مغامرة بتبدأ فيها؟</h2><p>خذ لك لفة على الألعاب… يمكن تلقى تحدّيك الجاي.</p></div><button className="text-link" onClick={()=>go('rides')}>كل الألعاب والتجارب<ArrowLeft size={17}/></button></div><div className="ride-grid">{featured.map(r=><RideCard key={r.slug} ride={r} onOpen={()=>go('detail/'+r.slug)} favorite={favorites.includes(r.slug)} onFavorite={()=>toggleFavorite(r.slug)}/>)}</div></section>
<section className="map-home-section"><div className="container"><div className="section-heading"><div><div className="eyebrow">اعرف سكتك</div><h2>الملاهي قدامك، قبل لا توصل.</h2><p>شوف الألعاب، اعرف المناطق، ولقِ نقطة تجمعكم.</p></div><Button variant="outline" onClick={()=>go('map')}>افتح الخريطة<ArrowUpRight size={18}/></Button></div><ParkMap compact onRide={s=>go('detail/'+s)}/></div></section>
<section className="section container journey-section"><div><div className="eyebrow">من أول لعبة لآخر ذكرى</div><h2>اختلاف جوّكم؟<br/>يزيد الوناسة.</h2><p>واحد يحب الارتفاع، والثاني يبي ألعاب العائلة.<br/>سكة ترتّب يوم يجمعكم، وتخلّي لكل واحد تجربته.</p><Button onClick={()=>go('create')}>خلّنا نرتّب الطلعة<ArrowLeft size={17}/></Button></div><div className="journey-ticket"><div className="ticket-cap"><Logo/><span>بطاقة وناسة</span></div><div className="ticket-perforation"/><div className="journey-step"><span>١</span><div><h3>قول لنا وش جوّك</h3><p>موعدك، مين معك، وألعابك المفضلة.</p></div></div><div className="journey-step"><span>٢</span><div><h3>نرتّب لكم سكتكم</h3><p>ألعاب وبريكات ووقت يجمع القروب.</p></div></div><div className="journey-step"><span>٣</span><div><h3>عيشوا المغامرة</h3><p>خلصت لعبة؟ علّمنا ونشوف اللي بعدها.</p></div></div><div className="ticket-bottom">SIKKA / THE GOOD DAY PASS <span>✦ ✦ ✦</span></div></div></section>
<section className="cta-banner container"><div><h2>جاهز ليوم ما تنساه؟</h2><p>أول خطوة في الوناسة… نختار سكتكم.</p></div><Button onClick={()=>go('create')}>يلا نبدأ<ArrowLeft size={19}/></Button><svg viewBox="0 0 500 200" aria-hidden="true"><path d="M0 150C90 10 160 270 260 90S400 20 500 40"/></svg></section>
</>;
if(['members','selection','meals','preview','payment','generating','plan','live','recap'].includes(page)&&!visit)return <div className="container page-space"><Empty title="خلّنا نبدأ بزيارة" description="جهّز طلعتك أو افتح زيارة محفوظة." action="جهّز زيارة" onClick={()=>go('create')}/><button className="demo-link" onClick={sample}>شوف تجربة كاملة بزيارة توضيحية</button></div>;
if(page==='rides'||page==='selection'||page==='preferences')return <div className="container page-space">{page==='selection'&&stepBar()}<PageTitle label={page==='selection'?'الخطوة ٣':'كل واحد له جوّه'} title={page==='preferences'?'ألعاب على ذوقك':page==='selection'?'وش بخاطرك تجرب؟':'اختَر مغامرتك الجاية'} description={page==='selection'?'اختيار الألعاب اختياري. تقدر تكمل ونرتّب لك اقتراحات.':'استكشف الألعاب والمناطق، واحفظ اللي يعجبك للزيارة الجاية.'}/><div className="catalog-tools"><div className="search-field"><Search size={19}/><Input placeholder="دور على لعبة أو منطقة…" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="فلتر المنطقة" value={land} onChange={e=>setLand(e.target.value)}><option value="ALL">كل المناطق</option>{Object.entries(lands).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><div className="result-count">{filtered.length} تجربة</div></div><div className="filter-chips">{[['ALL','كل الألعاب'],['THRILL','حماس عالي'],['FAMILY','مع العائلة'],['KIDS','للصغار'],['ARCADE','الكرنفال']].map(([k,l])=><button key={k} className={category===k?'active':''} onClick={()=>setCategory(k)}>{k==='THRILL'&&<Zap size={15}/>} {l}</button>)}</div>{page==='preferences'&&<div className="inline-note"><Heart size={17}/>المحفوظة عندك: {favorites.length} لعبة. اضغط القلب لتعديلها.</div>}<motion.div layout className="ride-grid">{filtered.filter(r=>page!=='preferences'||favorites.includes(r.slug)).map(r=><RideCard key={r.slug} ride={r} onOpen={()=>go('detail/'+r.slug)} onSelect={page==='selection'?()=>toggleRide(r.slug):undefined} selected={visit?.selected.includes(r.slug)} favorite={favorites.includes(r.slug)} onFavorite={()=>toggleFavorite(r.slug)}/>)}</motion.div>{filtered.length===0&&<Empty title="ما لقينا لعبة بهالوصف" description="جرّب اسم ثاني أو غيّر الفلتر." action="إزالة الفلاتر" onClick={()=>{setQuery('');setCategory('ALL');setLand('ALL')}}/>}{page==='preferences'&&!favorites.length&&<Empty title="لسه ما حفظت ألعاب" description="استكشف التجارب واضغط القلب عند اللعبة اللي تعجبك." action="استكشف الألعاب" onClick={()=>go('rides')}/>}<div className="source-notice"><Info size={16}/>أسماء الألعاب ومناطقها من كتالوج المشروع. شروط الأهلية فيه تجريبية وليست تصريح ركوب.</div>{page==='selection'&&<div className="sticky-actions"><span>{visit?.selected.length||0} ألعاب ضمن اختياراتك</span><Button onClick={()=>ensureVisit('meals')}>نكمل للبريكات<ArrowLeft size={17}/></Button></div>}</div>;
if(page==='map')return <div className="container page-space"><PageTitle label="استكشف بدون تسجيل" title="لفّ الملاهي قبل لا توصل" description="شوف الألعاب والمصليات ودورات المياه، واختَر نقطة البداية والوجهة لمسار مشي تقريبي."/><ParkMap onRide={s=>go('detail/'+s)}/><p className="source-notice"><Info size={16}/>الخريطة والمسارات من ملفات المشروع. المواقع والمداخل تحتاج تأكيدًا ميدانيًا؛ مدد المشي تقريبية.</p></div>;
if(page==='detail')return <><section className="detail-hero">{detail.photo?<Photo asset={detail.photo} alt={detail.name}/>:<div className={`ride-illustration land-${detail.land}`}><Mountain size={160}/></div>}<div className="detail-shade"/><div className="container detail-title"><button className="back-white" onClick={()=>go('rides')}><ArrowRight size={16}/>نرجع للألعاب</button><span>{detail.landName} / {categoryName[detail.category]}</span><h1 dir="ltr">{detail.name}</h1></div></section><div className="container detail-layout"><div><div className="eyebrow">تجربتك الجاية؟</div><h2>جرعة حماس على جوّك.</h2><p className="large-copy">{detail.description}</p><div className="detail-facts"><div><Mountain/><strong>{categoryName[detail.category]}</strong><span>نوع التجربة</span></div><div><MapPin/><strong>{detail.landName}</strong><span>المنطقة</span></div><div><Clock/><strong>غير متصل</strong><span>وقت الانتظار</span></div></div><div className="safety-note"><Shield size={24}/><div><h3>قبل ما تركب</h3><p>بيانات شروط الألعاب الحالية مصطنعة لمحاكاة التخطيط. ما نقدر نؤكد أهلية الركوب منها؛ راجع تعليمات المشغّل عند اللعبة.</p></div></div></div><aside className="choice-panel"><span className="yellow-label">خطّطها على كيفك</span><h2>هذي من ألعابك؟</h2><p>احفظها عشان ترجع لها، أو أضفها لطلعتك.</p><Button onClick={()=>{toggleFavorite(detail.slug);toast.success(favorites.includes(detail.slug)?'شِلناها من المحفوظة':'حفظناها لك')}}><Heart size={17} fill={favorites.includes(detail.slug)?'currentColor':'none'}/>{favorites.includes(detail.slug)?'محفوظة عندك':'احفظ اللعبة'}</Button><Button variant="outline" onClick={()=>{if(visit){if(!visit.selected.includes(detail.slug))toggleRide(detail.slug);go('selection');}else{setDraft(d=>({...d,selected:[detail.slug]}));go('create')}}}>أضفها للزيارة<Plus size={17}/></Button><button className="text-link" onClick={()=>go('map')}>وين موقعها؟<Navigation size={16}/></button></aside></div></>;
if(page==='visits')return <div className="container page-space"><PageTitle label="كل طلعة لها سكتها" title="وين الوناسة الجاية؟" description="زياراتك اللي نجهّز لها، واللي خلصت وباقي ذكراها."><Button onClick={()=>{setDraft({...initialVisit,id:'',name:'',date:'',arrival:'',members:[],selected:[]});go('create')}}><Plus size={18}/>طلعة جديدة</Button></PageTitle>{!visits.length?<><Empty title="أول طلعة تنتظرك" description="حدد الموعد ومين معك، وخلّ ترتيب اليوم علينا." action="نجهّز طلعتك" onClick={()=>go('create')}/><button className="demo-link" onClick={sample}>أو جرّب زيارة توضيحية جاهزة<ArrowLeft size={15}/></button></>:<div className="visits-grid">{visits.map((v,i)=><article className="visit-ticket" key={v.id}><Photo asset={i%2===0?'park':'iron'} alt="صور من Six Flags القدية"/><span className="visit-status">{v.status==='COMPLETED'?'خلصت الوناسة':v.status==='ACTIVE'?'حنا بالملاهي':v.paid?'الخطة جاهزة':'نجهّز لها'}</span><div className="visit-body"><small>Six Flags Qiddiya City</small><h2>{v.name}</h2><p><CalendarDays size={16}/>{v.date} <Users size={16}/>{v.members.length} أشخاص</p><div className="ticket-perforation"/><Button onClick={()=>openVisit(v)}>شوف سكتنا<ArrowLeft size={16}/></Button></div></article>)}</div>}</div>;
if(page==='create')return <div className="container page-space">{stepBar()}<PageTitle title="وش جوّ الطلعة؟" description="قول لنا التفاصيل… ومنها تبدأ سكتكم."/><form className="wizard-layout" onSubmit={e=>{e.preventDefault();const fields=new FormData(e.currentTarget);const visitName=String(fields.get('visitName')||draft.name).trim();const visitDate=String(fields.get('visitDate')||draft.date);const arrivalTime=String(fields.get('arrivalTime')||draft.arrival);if(!visitName||!visitDate){toast.error('نحتاج اسم الزيارة وتاريخها');return;}const v={...draft,name:visitName,date:visitDate,arrival:arrivalTime,id:draft.id||newId(),members:draft.id?draft.members:[user?.name||'أنا'],status:'DRAFT',paid:false,approved:false,completed:[],ratings:{}};setVisits(a=>draft.id?a.map(old=>old.id===v.id?v:old):[...a,v]);setActiveId(v.id);go('members');}}><div className="wizard-main"><div className="trip-types">{[['SOLO','لحالي',User],['FRIENDS','مع الأصحاب',Users],['FAMILY','مع العائلة',Heart]].map(([k,l,Icon]:any)=><button type="button" key={k} className={draft.type===k?'selected':''} onClick={()=>setDraft(d=>({...d,type:k}))}><Icon size={25}/><strong>{l}</strong>{draft.type===k&&<Check size={16}/>}</button>)}</div><Field label="وش اسم الطلعة؟"><Input name="visitName" required maxLength={80} value={draft.name} placeholder="مثل: طلعة الشباب" onChange={e=>setDraft(d=>({...d,name:e.target.value}))}/></Field><div className="field-grid"><Field label="متى الزيارة؟"><Input name="visitDate" type="date" required min={new Date().toLocaleDateString('en-CA')} value={draft.date} onChange={e=>setDraft(d=>({...d,date:e.target.value}))}/></Field><Field label="كم ساعة بتجلسون؟"><select value={draft.duration} onChange={e=>setDraft(d=>({...d,duration:Number(e.target.value)}))}>{[120,180,240,300,360,480].map(m=><option key={m} value={m}>{m/60} ساعات</option>)}</select></Field></div><Field label="وقت الوصول (اختياري)"><Input name="arrivalTime" type="time" value={draft.arrival} onChange={e=>setDraft(d=>({...d,arrival:e.target.value}))}/></Field><p className="field-hint">إذا ما تعرف وقت الوصول، نخلي الخطة بمدد من البداية ونحدد الساعة يومها.</p><Field label="وش أهم شي عندكم؟"><div className="choice-chips">{['ألعاب أكثر','انتظار أقل','مشي أقل'].map(x=><button type="button" className={draft.goal===x?'active':''} key={x} onClick={()=>setDraft(d=>({...d,goal:x}))}>{x}</button>)}</div></Field>{draft.type!=='SOLO'&&<Field label="تبون تلعبون سوا؟"><div className="choice-chips"><button type="button" className={draft.together==='TOGETHER'?'active':''} onClick={()=>setDraft(d=>({...d,together:'TOGETHER'}))}>نكون سوا</button><button type="button" className={draft.together==='SPLIT'?'active':''} onClick={()=>setDraft(d=>({...d,together:'SPLIT'}))}>نتفرق شوي ونتلاقى</button></div></Field>}<div className="switch-row"><div><h3>الصلاة ضمن الخطة</h3><p>نترك لها مساحة؛ الوقت الفعلي يحتاج خدمة أوقات الصلاة.</p></div><Switch checked={draft.prayer} onCheckedChange={v=>setDraft(d=>({...d,prayer:v}))}/></div><Button type="submit" className="wide">نكمل، مين معنا؟<ArrowLeft size={17}/></Button></div><aside className="wizard-aside"><Photo asset="falcon" alt="قطار Falcons Flight في القدية"/><div><span>الوناسة تبدأ بطلعة مرتّبة</span><h2>أنت اختَر الجو.<br/>وسكة ترتّب الطريق.</h2><p>كل خطوة تختارونها تخلي اليوم أقرب للي بخاطركم.</p></div></aside></form></div>;
if(['members','selection','meals','preview','payment','generating','plan','live','recap'].includes(page)&&!visit)return <div className="container page-space"><Empty title="خلّنا نبدأ بزيارة" description="جهّز طلعتك أو افتح زيارة محفوظة." action="جهّز زيارة" onClick={()=>go('create')}/><button className="demo-link" onClick={sample}>شوف تجربة كاملة بزيارة توضيحية</button></div>;
if(page==='members'||page==='family')return <div className="container page-space">{page==='members'&&stepBar()}<PageTitle title={page==='family'?'كل العائلة لها مكان':'مين معنا بالطلعة؟'} description={page==='family'?'أضف أفراد العائلة واحفظ بياناتهم الأساسية على هذا الجهاز.':'في نسخة العرض تقدر تضيف أسماء لتجربة تقسيم القروب.'}/><div className="people-grid">{(page==='family'?family.map(f=>f.name):visit!.members).map((name,i)=><article className="person-card" key={name+i}><span className={`person-avatar avatar-${i%3}`}>{name.slice(0,1)}</span><h3>{name}</h3><p>{i===0&&page==='members'?'منظّم الزيارة':'مشارك'}</p><span className="person-ready"><CheckCircle2 size={14}/>جاهز للوناسة</span>{i>0&&page==='members'&&<button className="icon-delete" aria-label={`حذف ${name}`} onClick={()=>updateVisit({members:visit!.members.filter((_,j)=>j!==i)})}><X size={15}/></button>}</article>)}<button className="add-person" onClick={()=>setModal('family')}><Plus size={28}/><strong>أضف {page==='family'?'فرد من العائلة':'شخص للطلعة'}</strong><span>نجرّب الزيارة مع بعض</span></button></div>{page==='members'&&<><div className="invite-box"><LinkIcon/><div><h3>دعوة الأصحاب</h3><p>الرابط في هذا العرض يفتح معاينة الدعوة فقط. الانضمام بين الأجهزة يحتاج ربط الخادم.</p></div><Button variant="outline" onClick={()=>{navigator.clipboard.writeText(location.origin+'/#invite').then(()=>toast.success('نسخنا رابط معاينة الدعوة')).catch(()=>toast.error('ما قدرنا ننسخ الرابط'));}}>نسخ الدعوة<Copy size={16}/></Button></div>{family.length>0&&<Button variant="outline" onClick={()=>{updateVisit({members:Array.from(new Set([...visit!.members,...family.map(f=>f.name)]))});toast.success('أضفنا أفراد العائلة للطلعة')}}>أضف عائلتي المحفوظة<Heart size={16}/></Button>}<div className="form-footer"><Button onClick={()=>go('selection')}>نكمل للألعاب<ArrowLeft size={17}/></Button></div></>}</div>;
if(page==='meals')return <div className="container page-space">{stepBar()}<PageTitle title="البريك جزء من الوناسة" description="نرتّب الأكل والسناك، ونخلّي وقت يجمعكم."/><div className="meal-choices">{[['بدون بريك',X],['وجبة',UtensilsCrossed],['سناك',Coffee],['وجبة وسناك',Heart],['نقررها بعدين',Clock]].map(([l,I]:any)=><button key={l} className={visit!.meal===l?'active':''} onClick={()=>updateVisit({meal:l})}><I size={24}/>{l}<small>{l==='سناك'?'نصف ساعة':l==='وجبة'?'ساعة كاملة':'على راحتكم'}</small></button>)}</div><div className="section-heading"><div><h2>وين نتلاقى على الأكل؟</h2><p>أماكن من كتالوج المنتزه، اختيارك محفوظ للمعاينة.</p></div></div><div className="meal-grid">{meals.map((m,i)=><button className={`meal-card ${m.style} ${visit!.restaurant===m.name?'selected':''}`} key={m.name} onClick={()=>updateVisit({restaurant:m.name})}><span className="meal-art">{i===2?<Coffee size={62}/>:<UtensilsCrossed size={62}/>}</span><small>{m.land} • {m.type}</small><h3 dir="ltr">{m.name}</h3><span>{visit!.restaurant===m.name?<><Check size={16}/>اختيارنا للبريك</>:<>نختار هذا المكان<Plus size={16}/></>}</span></button>)}</div><div className="form-footer"><span>الأكل ساعة، والسناك نصف ساعة.</span><Button onClick={()=>go('preview')}>راجع طلعتنا<ArrowLeft size={17}/></Button></div></div>;
if(page==='preview'||page==='payment')return <div className="container page-space">{page==='preview'&&stepBar()}<PageTitle title={page==='preview'?'هذي طلعتكم باختصار':'باقي خطوة ونضبط يومكم'} description="سكة خدمة لتخطيط الزيارة. تذاكر المنتزه تُشترى من المشغّل."/><div className="checkout-layout"><div className="checkout-main">{page==='preview'?<><h2>كل التفاصيل تمام؟</h2><div className="review-grid"><div><CalendarDays/><small>موعد الوناسة</small><strong>{visit!.date}</strong><span>{visit!.duration/60} ساعات • {visit!.arrival||'الوصول نحدده يومها'}</span></div><div><Users/><small>الصحبة</small><strong>{visit!.members.length} أشخاص</strong><span>{visit!.members.join('، ')}</span></div><div><Ticket/><small>الألعاب</small><strong>{visit!.selected.length} اختيارات</strong><span>{visit!.goal}</span></div><div><UtensilsCrossed/><small>وقت البريك</small><strong>{visit!.meal}</strong><span>{visit!.restaurant}</span></div></div><div className="locked-plan"><LockKeyhole size={32}/><h3>الجدول التفصيلي بعد التخطيط</h3><p>الخطط الفردية، خطة القروب، وتقسيم الأنشطة ونقاط اللقاء.</p></div><Button onClick={()=>go('members')} variant="outline">نعدّل بعض التفاصيل</Button></>:<><div className="demo-payment-notice"><Shield/><div><h3>معاينة الدفع فقط</h3><p>ما نطلب بيانات بطاقة ولا نسحب مبلغ. الدفع الفعلي يحتاج ربط Moyasar وتأكيده من الخادم.</p></div></div><div className="payment-methods"><span>mada</span><span>VISA</span><span>Apple Pay</span></div><div className="payment-demo-box"><LockKeyhole size={36}/><h3>الدفع الآمن يظهر هنا عند الربط</h3><p>تقدر تجرّب نجاح العملية أو تعثّرها بدون إدخال أي معلومات مالية.</p></div>{paymentState==='failed'&&<div className="error-note">المحاولة التجريبية ما اكتملت. تقدر تعيدها.</div>}<Button className="wide" onClick={()=>{setPaymentState('success');updateVisit({paid:true});toast.success('نجحت محاكاة الدفع — ما تم سحب أي مبلغ');go('generating')}}>جرّب نجاح الدفع<ArrowLeft size={17}/></Button><Button variant="outline" className="wide" onClick={()=>setPaymentState('failed')}>جرّب تعثّر الدفع</Button></>}</div><aside className="receipt"><span className="yellow-label">بطاقة طلعتكم</span><Logo/><h2>{visit!.name}</h2><p>Six Flags Qiddiya City</p><div className="ticket-perforation"/><dl><div><dt>الخدمة</dt><dd>تخطيط الزيارة</dd></div><div><dt>المشاركون</dt><dd>{visit!.members.length} أشخاص</dd></div><div><dt>المدة</dt><dd>{visit!.duration/60} ساعات</dd></div></dl><div className="receipt-total"><span>قيمة الخدمة</span><strong>تُحدّد عند الربط</strong></div>{page==='preview'&&<Button onClick={()=>go('payment')}>كمّل لمعاينة الدفع<ArrowLeft size={17}/></Button>}<small>الجدول في العرض توضيحي، ولا يمثل تخطيط ذكاء اصطناعي فعلي.</small></aside></div></div>;
if(page==='generating')return <div className="container generating"><div className="spinner-park"><Compass size={70}/><Sparkles size={25}/></div><div className="eyebrow">كل شي على جوّكم</div><h1>نرتّب سكتكم…</h1><p>هذي محاكاة تجهيز الخطة للعرض.</p><div className="generation-steps"><span><Check/>اختيارات الأعضاء</span><span><Loader2 className="spin"/>ترتيب الأنشطة والبريكات</span><span><Circle/>خطة القروب</span></div></div>;
if(page==='plan')return <div className="container page-space"><PageTitle label="سكتكم لليوم" title={visit!.name} description={`${visit!.date} • ${visit!.duration/60} ساعات • ${visit!.members.length} أشخاص`}><Button variant="outline" onClick={()=>go('members')}>شوف الأعضاء<Users size={16}/></Button></PageTitle>{!visit!.paid?<div className="locked-plan"><LockKeyhole size={36}/><h2>باقي خطوة قبل الخطة</h2><p>شوف المعاينة وجرّب خدمة التخطيط.</p><Button onClick={()=>go('preview')}>شوف المعاينة</Button></div>:<><div className="plan-toolbar"><div className="segmented"><button className={planTab==='group'?'active':''} onClick={()=>setPlanTab('group')}>خطة القروب<Users size={15}/></button><button className={planTab==='mine'?'active':''} onClick={()=>setPlanTab('mine')}>خطتي<User size={15}/></button></div><span className="soft-badge"><Sparkles size={14}/>خطة توضيحية للعرض</span></div><div className="inline-note"><Footprints size={17}/>الجدول توضيحي، وبين الألعاب مساحة انتقال افتراضية ١٠ دقائق.{visit!.selected.length>activities.filter(a=>a.kind==='RIDE').length&&` اختياراتك أكثر من الوقت المتاح؛ عرضنا ${activities.filter(a=>a.kind==='RIDE').length} ألعاب. زِد مدة الزيارة لتضيف الباقي.`}</div><div className="plan-layout"><div>{renderTimeline(planTab==='mine')}{visit!.prayer&&<div className="prayer-break"><Clock size={21}/><div><h3>الصلاة ما ننساها</h3><p>وقت الصلاة الفعلي يضاف عند ربط الخدمة بتاريخ الزيارة.</p></div></div>}</div><aside><div className="plan-overview"><h3>سكتكم باختصار</h3><div className="overview-stats"><div><strong>{activities.filter(a=>a.kind==='RIDE').length}</strong><span>ألعاب</span></div><div><strong>{visit!.duration/60}</strong><span>ساعات</span></div><div><strong>{visit!.members.length}</strong><span>مشاركين</span></div></div><Photo asset="iron" alt="Iron Rattler في القدية"/><h4>نتلاقى هنا</h4><p>{visit!.restaurant}</p><Button variant="outline" onClick={()=>go('map')}>شوفها بالخريطة<MapPin size={16}/></Button></div><div className="plan-approval"><h3>{visit!.approved?'خلاص، الخطة معتمدة':'كل شي على جوّكم؟'}</h3><p>{visit!.approved?'باقي نحدد الوصول ونبدأ المغامرة.':'القائد يراجع الخطة ويعتمدها قبل البداية.'}</p><Button onClick={()=>{if(!visit!.approved){updateVisit({approved:true,status:'APPROVED'});toast.success('اعتمدنا خطة العرض')}else{updateVisit({status:'ACTIVE'});go('live')}}}>{visit!.approved?'نبدأ الزيارة':'اعتمد الخطة'}<ArrowLeft size={17}/></Button><button className="text-link" onClick={()=>setModal('replan')}>نعدّل الخطة</button></div><p className="source-notice">الجدول والانتظار أمثلة. ما فيه اتصال مباشر بالمنتزه أو توليد AI حاليًا.</p></aside></div></>}</div>;
if(page==='live')return <div className="container page-space"><PageTitle label="حنا بالملاهي" title="الحين وقت الحماس!" description="نشاطك الحالي، ومكان اللقاء اللي يجمعكم."/><div className="live-progress"><div><CheckCheck size={19}/>{visit!.completed.length} من {activities.length} أنشطة مكتملة</div><div className="progress-track"><span style={{width:`${activities.length?visit!.completed.length/activities.length*100:0}%`}}/></div><span>{Math.round(activities.length?visit!.completed.length/activities.length*100:0)}٪</span></div>{!visit!.arrival&&<div className="arrival-box"><Clock/><div><h3>متى وصلتوا؟</h3><p>نحدد وقت بداية الجدول على وصولكم.</p></div><Input type="time" aria-label="وقت الوصول" onChange={e=>updateVisit({arrival:e.target.value})}/></div>}<div className="live-layout"><div className="current-activity">{current?<><div className="current-cover">{rides.find(r=>r.slug===current.key)?.photo?<Photo asset={rides.find(r=>r.slug===current.key)!.photo!} alt={current.title}/>:<div className="meal-art"><UtensilsCrossed size={80}/></div>}<span>الحين دوركم</span></div><div className="current-body"><small>{current.kind==='RIDE'?'النشاط الحالي':'وقت البريك'}</small><h2 dir={current.kind==='RIDE'?'ltr':'rtl'}>{current.title}</h2><p><Users size={16}/>{current.participants.join('، ')}</p><div className="current-time"><Clock/>{current.minutes} دقيقة ضمن الجدول التوضيحي</div><Button onClick={()=>{setRating(0);setCompletedFor(current.participants);setNote('');setModal('complete')}}>خلصت {current.kind==='RIDE'?'اللعبة':'البريك'}<Check size={18}/></Button><Button variant="outline" onClick={()=>setModal('delay')}>صار تغيير؟<RefreshCw size={16}/></Button></div></>:<Empty title="خلصتوا سكتكم!" description="مغامرة حلوة تستاهل نختمها بملخّص." action="شوف الملخص" onClick={()=>{updateVisit({status:'COMPLETED'});go('recap')}}/>}</div><div className="live-next"><div className="live-map-title"><h2>وجهتكم الجاية</h2><button className="text-link" onClick={()=>go('map')}>الخريطة كاملة<ArrowUpRight size={15}/></button></div><ParkMap compact onRide={s=>go('detail/'+s)}/><div className="next-meeting"><Flag/><div><small>نقطة تجمع القروب</small><h3>{visit!.restaurant}</h3><p>بريك الأكل • ساعة كاملة</p></div></div><Button variant="outline" onClick={()=>{updateVisit({status:'COMPLETED'});go('recap')}}>إنهاء الزيارة وشوف الملخص</Button></div></div></div>;
if(page==='recap')return <div className="container page-space"><section className="recap-hero"><div className="confetti">✦ <span>✧</span> ✦</div><PartyPopper size={45}/><span>خلصت الطلعة، وباقي الذكرى</span><h1>يا زين هاليوم!</h1><p>{visit!.name} • {visit!.date}</p><div className="recap-stats"><div><strong>{visit!.completed.filter(k=>rides.some(r=>r.slug===k)).length}</strong><span>ألعاب خلصتوها</span></div><div><strong>{visit!.members.length}</strong><span>أشخاص شاركوا الوناسة</span></div><div><strong>{Object.keys(visit!.ratings).length}</strong><span>تقييمات محفوظة</span></div></div></section><div className="section-heading"><div><h2>لحظاتكم، لعبة لعبة</h2><p>السجل مبني على اللي سجلته في نسخة العرض.</p></div></div><div className="ride-grid">{visit!.completed.filter(k=>rides.some(r=>r.slug===k)).map(k=>{const r=rides.find(r=>r.slug===k)!;return <div key={k}><RideCard ride={r} onOpen={()=>go('detail/'+k)}/><div className="rating-inline">{[1,2,3,4,5].map(n=><button key={n} aria-label={`تقييم ${r.name}: ${n}`} onClick={()=>updateVisit({ratings:{...visit!.ratings,[k]:n}})}><Star size={20} fill={(visit!.ratings[k]||0)>=n?'#ffc928':'none'}/></button>)}</div></div>})}</div>{!visit!.completed.length&&<div className="inline-note">ما تسجّل أي نشاط مكتمل في هالزيارة.</div>}<div className="cta-banner"><div><h2>نكرر الوناسة؟</h2><p>نحتفظ بالمدة والتفضيلات، ونختار موعد جديد.</p></div><Button onClick={()=>{setDraft({...visit!,id:'',date:'',paid:false,approved:false,completed:[],ratings:{},status:'DRAFT'});go('create')}}>نكرر الطلعة<RefreshCw size={17}/></Button></div></div>;
if(['login','signup','forgot'].includes(page))return <div className="container auth-layout"><div className="auth-art"><Photo asset="falcon" alt="Falcons Flight في القدية"/><div><Logo/><h2>الوناسة أحلى<br/>لما تكون مرتّبة.</h2><p>رفيقك من أول لعبة، لآخر ذكرى.</p></div></div><form className="auth-form" onSubmit={e=>{e.preventDefault();if(page==='forgot'){toast.info('الإرسال الفعلي غير مربوط. ما تم إرسال رسالة بريد.');return;}const data=new FormData(e.currentTarget);setUser({name:(data.get('name') as string)||'صديق سكة',height:'',thrill:'متوسط'});toast.success('دخلت وضع تجربة الواجهة — ليس حسابًا فعليًا');go(page==='signup'?'profile':'visits')}}><span className="soft-badge">نسخة عرض تفاعلية</span><h1>{page==='login'?'حيّاك من جديد':page==='signup'?'سكتك تبدأ هنا':'نرجعك لسكتك'}</h1><p>{page==='forgot'?'استعادة الحساب تظهر هنا بعد ربط خدمة البريد.':'جرّب تجربة الحساب. لا تُنشأ حسابات أو تُحفظ كلمات مرور في هذا العرض.'}</p>{page==='signup'&&<Field label="اسمك"><Input name="name" required autoComplete="given-name" placeholder="كيف نناديك؟"/></Field>}<Field label="البريد الإلكتروني"><Input type="email" required name="email" autoComplete="email" placeholder="name@example.com"/></Field>{page!=='forgot'&&<Field label="كلمة المرور التجريبية"><Input type="password" required minLength={8} name="password" autoComplete={page==='signup'?'new-password':'current-password'} placeholder="٨ أحرف على الأقل • لا تُحفظ"/></Field>}{page==='login'&&<button type="button" className="text-link" onClick={()=>go('forgot')}>نسيت كلمة المرور؟</button>}<Button type="submit" className="wide">{page==='forgot'?'طلب استعادة الحساب':page==='signup'?'جرّب إنشاء الحساب':'ادخل للتجربة'}<ArrowLeft size={17}/></Button><p className="auth-switch">{page==='login'?'ما عندك حساب؟':'عندك حساب؟'} <button type="button" onClick={()=>go(page==='login'?'signup':'login')}>{page==='login'?'ابدأ سكتك':'سجّل دخولك'}</button></p><button type="button" className="text-link" onClick={()=>go('home')}>كمل استكشاف بدون تسجيل<ArrowLeft size={16}/></button></form></div>;
if(page==='profile')return <div className="container page-space"><PageTitle title="خلّنا نعرف جوّك" description="بياناتك الأساسية تساعدنا نرتّب تجربة أقرب لك."/><div className="profile-layout"><aside className="profile-nav"><div className="person-avatar avatar-0">{user?.name?.slice(0,1)||'س'}</div><h2>{user?.name||'صديق سكة'}</h2><button className="active"><User/>ملف الزائر</button><button onClick={()=>go('family')}><Users/>أفراد العائلة</button><button onClick={()=>go('preferences')}><Heart/>ألعابي المحفوظة</button><button onClick={()=>go('privacy')}><Shield/>الخصوصية</button><button onClick={()=>{setUser(null);toast.info('طلعت من وضع تجربة الحساب');go('home')}}><LogOut/>خروج من التجربة</button></aside><form className="profile-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);setUser({name:String(f.get('name')),height:String(f.get('height')),thrill:String(f.get('thrill'))});toast.success('حفظنا ملفك على هذا الجهاز')}}><h2>ملفك، على جوّك</h2><Field label="اسمك"><Input key={user?.name} name="name" required defaultValue={user?.name||''} placeholder="كيف نناديك؟"/></Field><Field label="طولك بالسنتيمتر"><Input type="number" min="50" max="250" name="height" defaultValue={user?.height} placeholder="مثل: 175"/></Field><Field label="مستوى الحماس المفضّل"><select name="thrill" defaultValue={user?.thrill||'متوسط'}><option>هادئ</option><option>متوسط</option><option>عالي</option></select></Field><div className="inline-note"><Shield size={19}/>لا نطلب معلومات صحية حساسة في نسخة العرض. أهلية الركوب يؤكدها المشغّل.</div><Button type="submit">احفظ ملفي<Check size={17}/></Button></form></div></div>;
if(page==='privacy')return <div className="container page-space narrow-page"><PageTitle title="بياناتك بيدك" description="الإعدادات هنا تخص نسخة العرض على هذا الجهاز."/>{[['location','الموقع','مشاركة الموقع متوقفة افتراضيًا. تفعيله هنا تفضيل فقط؛ الموقع يُطلب عند ضغط زر الخريطة.'],['email','إشعارات البريد','ما نرسل بريدًا في نسخة العرض.'],['whatsapp','واتساب','ما نرسل رسائل واتساب في نسخة العرض.']].map(([k,t,d])=><div className="privacy-option" key={k}><Shield size={24}/><div><h3>{t}</h3><p>{d}</p></div><Switch checked={privacy[k as keyof typeof privacy]} onCheckedChange={v=>setPrivacy(p=>({...p,[k]:v}))}/></div>)}<div className="danger-zone"><h3>احذف بيانات نسخة العرض</h3><p>يمسح الزيارات والتفضيلات والملف المحفوظ على هذا الجهاز.</p><Button variant="outline" onClick={()=>setModal('delete')}><Trash2 size={16}/>مسح البيانات المحلية</Button></div></div>;
if(page==='notifications')return <div className="container page-space narrow-page"><PageTitle title="آخر أخبار سكتك" description="تحديثات محلية لزياراتك في نسخة العرض."/>{!visits.length?<Empty title="كل شي هادي هنا" description="لما تجهّز زيارة، تطلع تحديثاتها هنا." action="نجهّز زيارة" onClick={()=>go('create')}/>:visits.map(v=><button className="notification" key={v.id} onClick={()=>openVisit(v)}><span><Bell size={22}/></span><div><h3>{v.paid?'خطة الزيارة جاهزة':'طلعتك محفوظة، نكمّلها؟'}</h3><p>{v.name} • {v.date}</p></div><ArrowLeft size={18}/></button>)}</div>;
if(page==='invite')return <div className="container page-space narrow-page"><div className="invite-preview"><Users size={54}/><h1>مكانك معنا!</h1><p>هذي معاينة صفحة دعوة سكة. الانضمام لزيارة مشتركة بين الأجهزة يحتاج ربط الخادم.</p><Button onClick={()=>go('login')}>ادخل للتجربة<ArrowLeft size={17}/></Button><button className="text-link" onClick={()=>go('home')}>استكشف الملاهي أول</button></div></div>;
if(page==='sources')return <div className="container page-space narrow-page"><PageTitle title="صور حقيقية، ومصدر واضح" description="صور الألعاب الموثّقة تُحمّل من مصادرها مع نسبها لأصحابها. بقية الألعاب تستخدم رسومات تجريدية واضحة."/>{Object.entries(photos).map(([k,p])=><a key={k} href={p.source} target="_blank" rel="noreferrer" className="source-row"><div><h3>{k==='map'?'خريطة المنتزه':p.credit}</h3><span dir="ltr">{p.source}</span></div><ExternalLink size={18}/></a>)}<div className="inline-note">حقوق الصور لأصحابها. النسخة للاطلاع والعرض؛ يلزم التأكد من تراخيص الأصول قبل الاستخدام التجاري. بيانات الألعاب من مستودع سكة، وبيانات الشروط الحالية تجريبية.</div></div>;
if(page==='admin')return <div className="container page-space"><PageTitle label="معاينة لوحة الإدارة" title="وراء كل يوم حلو… ترتيب" description="عرض بيانات المنتزه، بدون صلاحيات فعلية أو تعديل للخادم."/><div className="admin-stats">{[[rides.length,'ألعاب في الكتالوج',Ticket],[Object.keys(lands).length,'مناطق في البيانات',Map],[visits.length,'زيارات على جهازك',CalendarDays],[family.length,'أفراد عائلة محفوظين',Users]].map(([n,l,I]:any)=><div key={l}><I size={24}/><strong>{n}</strong><span>{l}</span></div>)}</div><div className="catalog-tools"><div className="search-field"><Search size={18}/><Input placeholder="ابحث في الكتالوج…" value={query} onChange={e=>setQuery(e.target.value)}/></div><Button variant="outline" onClick={()=>{const blob=new Blob([JSON.stringify(rides,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sikka-catalogue.json';a.click();URL.revokeObjectURL(a.href)}}>تصدير الكتالوج</Button></div><div className="data-table"><table><thead><tr><th>اللعبة</th><th>المنطقة</th><th>النوع</th><th>مصدر الشروط</th><th>تفاصيل</th></tr></thead><tbody>{filtered.map(r=><tr key={r.slug}><td dir="ltr">{r.name}</td><td>{r.landName}</td><td>{categoryName[r.category]}</td><td><span className="demo-table-badge">تجريبية</span></td><td><Button size="sm" variant="ghost" onClick={()=>go('detail/'+r.slug)}>عرض<ArrowUpRight size={15}/></Button></td></tr>)}</tbody></table></div></div>;
return null;
}

return <MotionConfig reducedMotion="user"><div className="sikka-app"><div className="demo-banner"><span>نسخة عرض تفاعلية</span><p>خطّط وجرّب بحرية • البيانات محفوظة على جهازك • بدون دفع فعلي</p><button onClick={sample}>جرّب زيارة جاهزة<ArrowLeft size={13}/></button></div><header className="site-header"><div className="container header-inner"><a href="#home" className="brand-link" aria-label="سكة الرئيسية"><Logo/></a><nav>{navigation.map(n=><a key={n.key} href={'#'+n.key} className={page===n.key?'active':''}>{n.label}</a>)}</nav><div className="header-actions"><button className="icon-btn" aria-label="الإشعارات" onClick={()=>go('notifications')}><Bell size={20}/>{visits.length>0&&<i/>}</button><Button variant="ghost" className="account-btn" onClick={()=>go(user?'profile':'login')}><User size={17}/>{user?.name||'دخول'}</Button><Button className="header-plan" onClick={()=>go('create')}>خطّط يومك<Sparkles size={16}/></Button><Sheet open={menuOpen} onOpenChange={setMenuOpen}><SheetTrigger asChild><button className="mobile-menu-btn" aria-label="القائمة"><Menu size={25}/></button></SheetTrigger><SheetContent side="right" className="mobile-sheet"><SheetHeader><SheetTitle><Logo/></SheetTitle></SheetHeader><div className="mobile-nav">{navigation.map(n=><a key={n.key} href={'#'+n.key} onClick={()=>setMenuOpen(false)}><n.icon size={22}/>{n.label}</a>)}<a href="#team" onClick={()=>setMenuOpen(false)}><Users/>فريق سكة</a><a href="#profile" onClick={()=>setMenuOpen(false)}><User/>ملفي</a><a href="#family" onClick={()=>setMenuOpen(false)}><Users/>عائلتي</a><a href="#privacy" onClick={()=>setMenuOpen(false)}><Shield/>الخصوصية</a></div></SheetContent></Sheet></div></div></header>
<AnimatePresence mode="wait"><motion.main key={page} initial={reduced?false:{opacity:0,y:6}} animate={{opacity:1,y:0}} exit={reduced?undefined:{opacity:0}} transition={{duration:.18}}>{content()}</motion.main></AnimatePresence>
<footer className="site-footer"><div className="container footer-top"><div><a href="#home"><Logo/></a><p>الوناسة لها سكة.<br/>رفيقك الذكي قبل الزيارة، أثناءها، وبعدها.</p></div><div><h4>استكشف</h4><a href="#rides">الألعاب والتجارب</a><a href="#map">خريطة الملاهي</a><a href="#create">خطّط زيارتك</a></div><div><h4>سكتك</h4><a href="#visits">زياراتي</a><a href="#family">أفراد العائلة</a><a href="#preferences">ألعابي المحفوظة</a></div><div><h4>عن سكة</h4><a href="#privacy">الخصوصية</a><a href="#team">فريق سكة · لنكدن</a><a href="#sources">مصادر الصور والبيانات</a><a href="#admin">معاينة الإدارة</a></div></div><div className="container footer-bottom"><span>سكة © {new Date().getFullYear()} • مشروع عرض مستقل، غير تابع للمشغّل.</span><span>صُنعت للوناسة، على جوّكم ✦</span></div></footer>
<nav className="mobile-bottom-nav">{navigation.map(n=><a key={n.key} href={'#'+n.key} className={page===n.key?'active':''}><n.icon size={21}/><span>{n.key==='rides'?'الألعاب':n.label}</span></a>)}</nav>
<Dialog open={modal!==null} onOpenChange={v=>{if(!v)setModal(null)}}><DialogContent className="sikka-dialog"><DialogHeader><DialogTitle>{modal==='complete'?'كفو! مين خلص معك؟':modal==='delay'?'وش صار معكم؟':modal==='replan'?'نعدّل الجزء المتأثر؟':modal==='family'?'مين بنضيف للوناسة؟':'نمسح بيانات نسخة العرض؟'}</DialogTitle><DialogDescription>{modal==='delete'?'بيانات هذا الجهاز فقط؛ ما فيه حذف من خادم فعلي.':modal==='replan'?'اقتراح محلي للتصميم. ما فيه توليد AI أو تعديل فعلي على الخادم.':'التغييرات في هذه المعاينة محفوظة محليًا على جهازك.'}</DialogDescription></DialogHeader>
{modal==='family'&&<form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=String(f.get('name')).trim();if(!name)return;const person={name,age:String(f.get('age')||''),height:String(f.get('height')||'')};if(page==='family')setFamily(a=>[...a,person]);else if(visit)updateVisit({members:[...visit.members,name]});setModal(null);toast.success('أضفناه للوناسة')}}><Field label="الاسم"><Input name="name" required maxLength={40} placeholder="اكتب الاسم"/></Field><div className="field-grid"><Field label="العمر (اختياري)"><Input name="age" type="number" min="1" max="120"/></Field><Field label="الطول (اختياري)"><Input name="height" type="number" min="50" max="250"/></Field></div><Button className="wide" type="submit">أضف<Plus size={17}/></Button></form>}
{modal==='complete'&&current&&<><h3 className="dialog-activity">{current.title}</h3><div className="member-checks">{visit!.members.map(n=><label key={n}><input type="checkbox" checked={completedFor.includes(n)} onChange={()=>setCompletedFor(a=>a.includes(n)?a.filter(x=>x!==n):[...a,n])}/><span>{n}</span></label>)}</div>{current.kind==='RIDE'&&<div className="rating-select"><span>كيف كانت التجربة؟</span><div>{[1,2,3,4,5].map(n=><button key={n} aria-label={`تقييم ${n}`} onClick={()=>setRating(n)}><Star fill={rating>=n?'#ffc928':'none'} size={29}/></button>)}</div></div>}<Field label="ملاحظتك (اختياري)"><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="وش أكثر شي عجبك؟"/></Field><Button disabled={!completedFor.length} onClick={()=>{updateVisit({completed:[...new Set([...visit!.completed,current.key])],ratings:rating?{...visit!.ratings,[current.key]:rating}:visit!.ratings});setModal(null);toast.success('سجلنا الإنجاز في زيارة العرض')}}>احفظ الإنجاز<Check size={17}/></Button></>}
{modal==='delay'&&<><Field label="سبب التأخير"><select value={delayReason} onChange={e=>setDelayReason(e.target.value)}>{['راحة','لعبة خارج الخطة','انتظار أطول','سبب آخر'].map(s=><option key={s}>{s}</option>)}</select></Field><Field label="التفاصيل"><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="وش صار وكم تحتاجون وقت؟"/></Field><Button onClick={()=>{setPendingReplan(true);setModal('replan')}}>راجع اقتراح التعديل<ArrowLeft size={17}/></Button></>}
{modal==='replan'&&<><div className="comparison-grid"><div><small>الخطة الحالية</small><h3>{current?.title||'أنشطة الزيارة'}</h3><p>تظل كما هي إلى اعتمادك.</p></div><div><small>المقترح للعرض</small><h3>نراجع اختيارات الألعاب</h3><p>تقدر تبدّل نشاطًا وتبقي بقية الزيارة.</p></div></div><Button onClick={()=>{setModal(null);setPendingReplan(false);go('selection');toast.info('اختَر التغيير ثم ارجع للخطة. لا تعديل تلقائي على الأنشطة.')}}>راجع الاختيارات<ArrowLeft size={16}/></Button><Button variant="outline" onClick={()=>setModal(null)}>نخلي الخطة الحالية</Button></>}
{modal==='delete'&&<><Button variant="destructive" onClick={()=>{setVisits([]);setFavorites([]);setUser(null);setFamily([]);setActiveId('');setPrivacy({location:false,email:true,whatsapp:false});setModal(null);toast.success('مسحنا بيانات العرض المحلية');go('home')}}>امسح البيانات المحلية<Trash2 size={17}/></Button><Button variant="outline" onClick={()=>setModal(null)}>خلها محفوظة</Button></>}
</DialogContent></Dialog><Toaster position="top-center" richColors dir="rtl"/></div></MotionConfig>;
}
